{"description": "Run bash echo and catch missing file read", "code": "
const bashResult = await tools.bash({
  command: "echo CODE_ROUND_OK",
  description: "Echo CODE_ROUND_OK"
});

let readError = null;
try {
  await tools.read({ file_path: "missing.txt" });
} catch (e) {
  readError = {
    toolName: e.toolName,
    message: e.message
  };
}

return { bash: bashResult.stdout.text.trim(), readError };
"}

